discrete ControlSystem
port:
    event input real ReceiveGCodeFile;
    event output real SendPositionControlInstruction;
    event output real SendSpeedControlInstruction;
    event output real SendAccelerationControlInstruction;
    event output real SendToolLoadInstruction;
    event output real SendCoolantOnInstruction;
    event output real SendLubricationOnInstruction;
    event output real SendStopSignal;
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(ReceiveGCodeFile) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State3);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State4);
            out
                send(SendPositionControlInstruction, 1);
                send(SendSpeedControlInstruction, 1);
                send(SendAccelerationControlInstruction, 1);
                send(SendToolLoadInstruction, 1);
                send(SendCoolantOnInstruction, 1);
                send(SendLubricationOnInstruction, 1);
        end;
    end;

    state State4
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(State1);
        end;
    end;
end;
end;

