import architectureModels.ControlSystem as Control;
import architectureModels.ServoDriveSystem as Servo;
import architectureModels.MechanicalSystem as Mechanical;
import architectureModels.ToolManagementSystem as Tool;
import architectureModels.CoolingAndLubricationSystem as Cooling;
import architectureModels.SafetyAndMonitoringSystem as Safety;

part:
    Control control;
    Servo servo;
    Mechanical mechanical;
    Tool tool;
    Cooling cooling;
    Safety safety;

connection:
    connect(control.SendPositionControlInstruction, servo.ReceivePositionControlInstruction);
    connect(control.SendSpeedControlInstruction, servo.ReceiveSpeedControlInstruction);
    connect(control.SendAccelerationControlInstruction, servo.ReceiveAccelerationControlInstruction);
    connect(control.SendToolLoadInstruction, mechanical.ReceiveToolLoadInstruction);
    connect(control.SendCoolantOnInstruction, cooling.ReceiveCoolantOnInstruction);
    connect(control.SendLubricationOnInstruction, cooling.ReceiveLubricationOnInstruction);
    connect(control.SendStopSignal, safety.AbnormalConditionDetected);
end;
